/**
 * The sun's light in the eye — CODE-SPLIT.
 *
 * A REGISTERED CHUNK MANIFEST MODULE (MANIFEST_MODULES and ALLOWLIST in
 * tooling/check-shader-imports.mjs): the import site of the lens flare
 * system, the textures its pictures are drawn in and the rendering pipeline
 * whose bloom glows around what is brightest; loaded only by dynamic
 * `import()` from the planet view, for a world that wants either.
 *
 * The flare is a chain of soft glows, rings and discs from the sun through
 * the middle of the view, its pictures made here rather than fetched. How
 * strongly it shows is the view's to say each frame (the sun's height, the
 * air and cloud in front of it, the ground in the way, and the world's own
 * strength), so the flare system's own picking is off.
 */
import { LensFlareSystem } from '@babylonjs/core/LensFlares/lensFlareSystem';
import { LensFlare } from '@babylonjs/core/LensFlares/lensFlare';
import { RawTexture } from '@babylonjs/core/Materials/Textures/rawTexture';
import { Constants } from '@babylonjs/core/Engines/constants';
import { ToHalfFloat } from '@babylonjs/core/Misc/halfFloat';
import { DefaultRenderingPipeline } from '@babylonjs/core/PostProcesses/RenderPipeline/Pipelines/defaultRenderingPipeline';
import { TransformNode } from '@babylonjs/core/Meshes/transformNode';
// The flare system asks the scene for a pick toward the sun, which needs the ray's side effect on the scene.
import { Ray } from '@babylonjs/core/Culling/ray';
import { Color3 } from '@babylonjs/core/Maths/math.color';
import { Vector3 } from '@babylonjs/core/Maths/math.vector';
import type { Camera } from '@babylonjs/core/Cameras/camera';
import type { AbstractMesh } from '@babylonjs/core/Meshes/abstractMesh';
import type { Scene } from '@babylonjs/core/scene';
import type { SunEffectsHandle } from './planetView';

export type FlareKind = 'glow' | 'ring' | 'disc';

/**
 * A flare picture, `size` pixels square, as red, green, blue and alpha from 0 to 1:
 * grey to white, each channel a soft glow falling to nothing at the edge, a thin ring at
 * three quarters of the radius, or a disc with a soft edge.
 *
 * The numbers are not rounded to bytes. A wide glow spends most of its width below one byte's worth of light, and
 * a view drawn in high dynamic range and brightened for the screen shows the step from one byte to none as an edge
 * across a dark sky. The picture is nothing along its border texels, so it never ends at the edge of what is drawn.
 */
export function flareImage(kind: FlareKind, size: number): Float32Array {
  const out = new Float32Array(size * size * 4);
  const half = size / 2;
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const r = Math.hypot(x + 0.5 - half, y + 0.5 - half) / (half - 1);
      let a: number;
      if (r >= 1) a = 0;
      else if (kind === 'glow') a = Math.pow(1 - r, 2.2);
      else if (kind === 'ring') a = Math.exp(-(((r - 0.75) / 0.06) ** 2)) * (1 - r) * 4;
      else a = r < 0.8 ? 0.55 : 0.55 * (1 - (r - 0.8) / 0.15);
      const i = (y * size + x) * 4;
      // Flares are added to the view, so the picture is in its colour; its alpha matches.
      out[i] = out[i + 1] = out[i + 2] = out[i + 3] = Math.min(1, Math.max(0, a));
    }
  }
  return out;
}

/** A flare picture as the engine keeps it: half floats, which every device can smooth between texels. */
export function flareTexels(image: Float32Array): Uint16Array {
  const out = new Uint16Array(image.length);
  for (let i = 0; i < image.length; i++) out[i] = ToHalfFloat(image[i]!);
  return out;
}

/** The chain: its size on screen, its place on the line from the middle of the view (0) to the sun (1) and past the middle (below 0), its colour, its picture. */
// A wide soft bloom of light about the sun, the eye's own scatter, and a few faint ghosts, as a good lens shows them: the glow
// the air scatters about the sun is the sky's (atmosphere.ts sunGlow), so the flare adds only what the eye and lens do.
const FLARES: [number, number, [number, number, number], FlareKind][] = [
  [1.1, 1, [0.32, 0.3, 0.27], 'glow'],
  [0.35, 1, [0.45, 0.42, 0.36], 'glow'],
  [0.09, 0.55, [0.07, 0.1, 0.14], 'disc'],
  [0.05, 0.3, [0.08, 0.12, 0.09], 'disc'],
  [0.22, -0.2, [0.06, 0.07, 0.11], 'ring'],
];
/** How far along the sun's direction the flare's emitter sits, in metres from the eye. */
const EMITTER_M = 1000;
/** Bloom at the world's full strength. */
const BLOOM_WEIGHT = 0.35;
/** The brightness past which things glow where the scene is drawn in high dynamic range: the screen's 0.8, as light. */
const BLOOM_THRESHOLD_LINEAR = 0.6;

/** The mark a model leaves on a material that is a picture of what lies beyond the world: its sky, the ground far below. */
const BACKDROP_KEY = 'veml_backdrop';

/**
 * Whether a mesh hides the sun from an eye behind it. Two kinds do not, and both are the model's own to say:
 * a material drawn blended is seen through, as window glass is; and a material the model marks as backdrop
 * (`veml_backdrop` in its glTF extras, kept beside it by the loader) is a picture of what lies beyond the world,
 * the sun with it, so it is never in front of the sun. A cut-out material hides it: its holes are not asked about.
 */
export function hidesSun(mesh: AbstractMesh): boolean {
  if (!mesh.isPickable || !mesh.isVisible || !mesh.isEnabled()) return false;
  const material = mesh.material;
  if (!material) return true;
  if (material.needAlphaBlendingForMesh(mesh)) return false;
  const extras = (material.metadata as { gltf?: { extras?: Record<string, unknown> } } | null | undefined)?.gltf?.extras;
  return !extras?.[BACKDROP_KEY];
}

/**
 * Whether nothing stands between the eye and the sun, as far as `reach`: for a world with no planet, whose view
 * has no ground of its own to ask. It answers at the first thing met that hides the sun, not the nearest.
 */
export function sunInSight(scene: Scene, eye: { x: number; y: number; z: number }, toward: { x: number; y: number; z: number }, reach: number): boolean {
  const ray = new Ray(new Vector3(eye.x, eye.y, eye.z), new Vector3(toward.x, toward.y, toward.z), reach);
  return scene.pickWithRay(ray, hidesSun, true)?.hit !== true;
}

/**
 * `hdr`: the scene is drawn in high dynamic range under the bloom, and turned into what the screen shows after it, so
 * what is brighter than white (a high-dynamic-range sky's sun) glows as bright as it is. A planet's view does not ask
 * for it: its sky is drawn for the screen, and its bloom is of that.
 */
export function createSunEffects(scene: Scene, camera: Camera, opts: { engineKind?: string; bloom: boolean; hdr?: boolean }): SunEffectsHandle {
  const emitter = new TransformNode('sunFlareEmitter', scene);
  const system = new LensFlareSystem('sunFlare', emitter, scene);
  // The view says how much of the sun is in view; the system's own picking would test every mesh each frame.
  system.meshesSelectionPredicate = () => false;
  const textures: RawTexture[] = [];
  const smoothHalfFloats = scene.getEngine().getCaps().textureHalfFloatLinearFiltering === true;
  const flares = FLARES.map(([size, position, color, kind]) => {
    const flare = new LensFlare(size, position, new Color3(...color), '', system);
    const image = flareImage(kind, 64);
    // A device that cannot smooth half floats would draw them as blocks: it gets the picture in bytes.
    const texture = smoothHalfFloats
      ? RawTexture.CreateRGBATexture(flareTexels(image), 64, 64, scene, false, false, Constants.TEXTURE_BILINEAR_SAMPLINGMODE, Constants.TEXTURETYPE_HALF_FLOAT)
      : RawTexture.CreateRGBATexture(Uint8Array.from(image, (v) => Math.round(255 * v)), 64, 64, scene, false, false);
    textures.push(texture);
    flare.texture = texture;
    return { flare, color: new Color3(...color) };
  });
  let pipeline: DefaultRenderingPipeline | undefined;
  if (opts.bloom) {
    pipeline = new DefaultRenderingPipeline('planetBloom', true, scene, [camera]);
    pipeline.imageProcessingEnabled = opts.hdr === true;
    pipeline.fxaaEnabled = false;
    pipeline.bloomEnabled = true;
    pipeline.bloomThreshold = opts.hdr ? BLOOM_THRESHOLD_LINEAR : 0.8;
    pipeline.bloomKernel = 64;
    pipeline.bloomScale = 0.5;
    pipeline.bloomWeight = 0;
  }
  return {
    update(eye, sun, flare, bloom, tint) {
      emitter.position.set(eye.x + sun.x * EMITTER_M, eye.y + sun.y * EMITTER_M, eye.z + sun.z * EMITTER_M);
      system.isEnabled = flare > 0.005;
      // Coloured as the sun's light is where it reaches the eye: orange at sunset.
      const [tr, tg, tb] = tint ?? [1, 1, 1];
      for (const f of flares) f.flare.color = new Color3(f.color.r * tr * flare, f.color.g * tg * flare, f.color.b * tb * flare);
      if (pipeline) {
        pipeline.bloomEnabled = bloom > 0;
        pipeline.bloomWeight = BLOOM_WEIGHT * bloom;
      }
    },
    dispose() {
      pipeline?.dispose();
      system.dispose();
      for (const t of textures) t.dispose();
      emitter.dispose();
    },
  };
}
